function simpleHash(str) {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash) + str.charCodeAt(i);
    hash = hash & hash;
  }
  return (hash >>> 0).toString(16);
}

// Questions whose ANSWER depends on WHO is asking. These must never share a
// cache entry between visitors: an answer of "you are Mariam" stored under
// hash("who am i") would be replayed to the next person who asks it.
const PERSONAL = /(who am i|what'?s my name|what is my name|my name|do you know me|know who i am|recogni[sz]e me|who do you see|من انا|من أنا|ما اسمي|شو اسمي|اسمي|تعرفني|هل تعرفني|بتعرفني)/;

const items = $input.all();
return items.map(item => {
  const raw = item.json.userText || '';
  const normalized = raw.toLowerCase().trim().replace(/[^\w\s\u0600-\u06FF]/g, '').replace(/\s+/g, ' ');
  const visitorName = String(item.json.visitorName || '').trim();
  const personal = PERSONAL.test(normalized);

  // Any answer produced while the agent knows a name may CONTAIN that name —
  // it greets people it recognises, so even "when was IUL established" comes
  // back as "Hello Mariam, ...". Such an answer can never be shared, so the
  // key is per-visitor whenever a visitor is known, not merely when the
  // question is personal. Measured the hard way: the first version keyed only
  // personal questions and promptly cached a named greeting under the shared
  // FAQ entry.
  //
  // Unrecognised visitors — the common case at a public desk — still share one
  // cache entry per question, so hit rate is unaffected for them.
  const keyBase = visitorName
    ? normalized + '|visitor:' + visitorName.toLowerCase()
    : normalized;

  item.json.normalizedQuestion = normalized;
  item.json.questionHash = simpleHash(keyBase);
  item.json.isPersonalQuestion = personal;
  item.json.visitorName = visitorName;
  // Marked so the agent can tell camera output from user-typed text.
  item.json.visitorContext = visitorName
    ? '\n\n[kiosk camera: the person at the kiosk is ' + visitorName + ']'
    : '';
  item.json.startedAt = Date.now();
  return item;
});

let parsed = {};
try { parsed = JSON.parse($json.cachedValue); } catch (e) { parsed = {}; }
const rawText = $('Normalize & Hash Question').first().json.userText;
return [{
  json: {
    answer: parsed.answer || '',
    question: parsed.question || rawText,
    rawQuestion: parsed.rawQuestion || '',
    corrections: Array.isArray(parsed.corrections) ? parsed.corrections : [],
    wantsAudio: String($('Webhook').item.json.body?.wantsAudio) !== 'false',
    matchType: ($('Fetch Semantic Hit').isExecuted ? 'semantic_hit' : 'cache_hit'),
    audioBase64: parsed.audioBase64 || '',
    audioMime: parsed.audioMime || ''
  }
}];

// Aggregate all TTS chunk outputs, concatenate PCM, insert silence between chunks,
// then wrap in a single WAV container.

// The answer can arrive from any of three upstream branches: a fresh agent
// answer, a clarification reply, or a cache hit. Referencing a node that did
// not execute THROWS, so probe rather than assume which one ran — and degrade
// to an empty answer instead of failing the whole turn if none of them did.
function pickSource(name) {
  try {
    return $(name).isExecuted ? $(name).first().json : null;
  } catch (e) {
    return null;
  }
}
const source = pickSource('Keep Answer Text')
  || pickSource('Build Clarification Reply')
  || pickSource('Parse Cached Response')
  || {};
const answer = source.answer || '';
const question = source.question || '';

// Graceful no-audio fallback
const NO_AUDIO = [{ json: { answer, question, audioMime: '', audioBase64: '' } }];

// Collect all items, sorted by chunkIndex
const items = $input.all();
if (!items || items.length === 0) return NO_AUDIO;

// Sort by chunkIndex (should already be in order, but be safe)
items.sort((a, b) => (a.json.chunkIndex ?? 0) - (b.json.chunkIndex ?? 0));

// Extract PCM buffers and sample rates from each chunk
const pcmBuffers = [];
const sampleRates = [];

for (const item of items) {
  const cands = item.json.candidates;
  if (!cands || !cands[0] || !cands[0].content || !cands[0].content.parts || !cands[0].content.parts[0]) {
    // Missing audio data for this chunk — degrade gracefully
    return NO_AUDIO;
  }
  const part = cands[0].content.parts[0];
  const pcmB64 = part?.inlineData?.data || part?.inline_data?.data;
  if (!pcmB64) return NO_AUDIO;

  const mime = part?.inlineData?.mimeType || part?.inline_data?.mime_type || '';
  const m = mime.match(/rate=(\d+)/);
  const sr = m ? parseInt(m[1], 10) : 24000;

  pcmBuffers.push(Buffer.from(pcmB64, 'base64'));
  sampleRates.push(sr);
}

// Verify all chunks have the same sample rate; if not, fall back to first chunk only
const baseSampleRate = sampleRates[0];
const allSameRate = sampleRates.every(r => r === baseSampleRate);

let combinedPcm;
if (!allSameRate) {
  // Sample rate mismatch — use only first chunk to avoid garbled audio
  combinedPcm = pcmBuffers[0];
} else if (pcmBuffers.length === 1) {
  combinedPcm = pcmBuffers[0];
} else {
  // Insert ~150ms silence (zero-filled 16-bit mono PCM) between chunks
  const silenceByteCount = Math.round(baseSampleRate * 0.15) * 2; // 16-bit = 2 bytes/sample
  const silence = Buffer.alloc(silenceByteCount, 0);

  const parts = [];
  for (let i = 0; i < pcmBuffers.length; i++) {
    parts.push(pcmBuffers[i]);
    if (i < pcmBuffers.length - 1) parts.push(silence);
  }
  combinedPcm = Buffer.concat(parts);
}

// Build 44-byte WAV header (mono, 16-bit LE)
const sampleRate = baseSampleRate;
const channels = 1;
const bitsPerSample = 16;
const byteRate = sampleRate * channels * bitsPerSample / 8;
const blockAlign = channels * bitsPerSample / 8;

const h = Buffer.alloc(44);
h.write('RIFF', 0);
h.writeUInt32LE(36 + combinedPcm.length, 4);
h.write('WAVE', 8);
h.write('fmt ', 12);
h.writeUInt32LE(16, 16);
h.writeUInt16LE(1, 20);          // PCM format
h.writeUInt16LE(channels, 22);
h.writeUInt32LE(sampleRate, 24);
h.writeUInt32LE(byteRate, 28);
h.writeUInt16LE(blockAlign, 32);
h.writeUInt16LE(bitsPerSample, 34);
h.write('data', 36);
h.writeUInt32LE(combinedPcm.length, 40);

const wav = Buffer.concat([h, combinedPcm]);

return [{ json: { answer, question, audioMime: 'audio/wav', audioBase64: wav.toString('base64') } }];

function simpleHash(str) {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash) + str.charCodeAt(i);
    hash = hash & hash;
  }
  return (hash >>> 0).toString(16);
}

// Greeting / small-talk phrases (EN + AR). Matched on word/phrase boundaries
// (padded with spaces) so short tokens like "hi" don't match inside other
// words (e.g. "history"). Tune this list as real traffic comes in.
const GREETING_PHRASES = [
  'hello', 'hi', 'hey', 'good morning', 'good evening', 'good afternoon',
  'thanks', 'thank you', 'bye', 'goodbye',
  'مرحبا', 'السلام عليكم', 'أهلا', 'شكرا', 'مع السلامة', 'صباح الخير', 'مساء الخير'
];

// Non-answer / "I don't know" phrases the model tends to emit (EN + AR).
// Matched as plain substrings against the lowercased answer. Tune this list
// as real traffic comes in.
const UNKNOWN_PHRASES = [
  "i don't have", "i do not have", "i'm not sure", "i am not sure",
  "no information", "not available", "cannot find", "can't find",
  "couldn't find", "unable to find", "don't know", "do not know",
  "no data", "please contact", "i'm sorry",
  "لا أملك", "لا أعرف", "لا تتوفر", "غير متوفر", "لا يوجد", "لم أجد", "يرجى التواصل", "عذرا",
  // Scope-refusal phrasing observed in real answers (model has no fixed fallback sentence).
  "i am sorry", "i can only", "i can only provide", "i can only answer", "i can only help",
  "outside my scope", "outside of my scope",
  "يمكنني فقط", "أستطيع فقط", "خارج نطاق"
];

function isGreeting(text) {
  const padded = ' ' + String(text || '').toLowerCase().trim() + ' ';
  return GREETING_PHRASES.some(p => padded.includes(' ' + p + ' ') || padded.trim() === p);
}

const items = $input.all();

return items.map(item => {
  // --- core fields (unchanged behavior) ---
  let answer = '';
  let question = '';
  let matchType = 'fresh';
  try { answer = item.json.answer || ''; } catch (e) { answer = ''; }
  try { question = item.json.question || ''; } catch (e) { question = ''; }
  try { matchType = item.json.matchType || 'fresh'; } catch (e) { matchType = 'fresh'; }

  const normalizedAnswer = answer.toLowerCase().trim().replace(/\s+/g, ' ');

  // The client tags each turn's origin (sendChat in web/src/lib/api.ts), because
  // speech arrives here already transcribed and is otherwise indistinguishable
  // from typing. Anything absent or unrecognised reads as 'text'.
  let inputType = 'text';
  try {
    inputType = $('Set userText (Text)').first().json.inputType === 'audio'
      ? 'audio'
      : 'text';
  } catch (e) {
    inputType = 'text';
  }

  let respondedWithAudio = false;
  try { respondedWithAudio = !!item.json.wantsAudio; } catch (e) { respondedWithAudio = false; }

  // --- new fields (all guarded — this node must never throw) ---

  // sessionId from the webhook body (works for both JSON and multipart turns)
  let sessionId = null;
  try {
    sessionId = $('Webhook').first().json.body?.sessionId || null;
  } catch (e) {
    sessionId = null;
  }

  // rawQuestion / corrections from Correct Domain Terms (typo-tolerance layer)
  let rawQuestion = '';
  let corrections = [];
  try {
    const cdt = $('Correct Domain Terms').first().json;
    rawQuestion = cdt.userTextRaw || '';
    corrections = Array.isArray(cdt.corrections) ? cdt.corrections : [];
  } catch (e) {
    // Cache-hit path: Correct Domain Terms never ran. Fall back to the
    // fields Parse Cached Response now surfaces from the cached blob.
    try {
      rawQuestion = item.json.rawQuestion || '';
      corrections = Array.isArray(item.json.corrections) ? item.json.corrections : [];
    } catch (e2) {
      rawQuestion = '';
      corrections = [];
    }
  }

  // questionHash / normalizedQuestion / startedAt from Normalize & Hash Question
  let questionHash = null;
  let normalizedQuestion = null;
  let startedAt = null;
  try {
    const normJson = $('Normalize & Hash Question').first().json;
    questionHash = normJson.questionHash || null;
    normalizedQuestion = normJson.normalizedQuestion || null;
  } catch (e) {
    questionHash = null;
    normalizedQuestion = null;
  }
  try {
    // Prefer the branch-specific start mark (captures Groq STT time on
    // voice turns); fall back to Normalize & Hash Question's own
    // startedAt if the branch value is unavailable (e.g. mid-deploy).
    // Single start mark. The branch-specific mark existed to capture Groq STT
    // time on voice turns; transcription now happens in the separate STT Webhook
    // workflow, so this figure excludes it.
    const normJson2 = $('Normalize & Hash Question').first().json;
    startedAt = typeof normJson2.startedAt === 'number' ? normJson2.startedAt : null;
  } catch (e) {
    startedAt = null;
  }

  // latencyMs — never negative/garbage; null when we can't compute it
  let latencyMs = null;
  try {
    if (typeof startedAt === 'number' && !Number.isNaN(startedAt)) {
      const diff = Date.now() - startedAt;
      latencyMs = (Number.isFinite(diff) && diff >= 0) ? diff : null;
    }
  } catch (e) {
    latencyMs = null;
  }

  // intent — greeting/small-talk vs a real question
  let intent = 'question';
  try {
    intent = isGreeting(normalizedQuestion || question) ? 'greeting' : 'question';
  } catch (e) {
    intent = 'question';
  }

  // language — Arabic script detected in the question
  let language = 'en';
  try {
    language = /[\u0600-\u06FF]/.test(question) ? 'ar' : 'en';
  } catch (e) {
    language = 'en';
  }

  // isUnknown — only for real questions; greetings are never unknown
  let isUnknown = false;
  try {
    if (intent === 'question') {
      const a = answer.trim();
      if (a === '') {
        isUnknown = true;
      } else {
        const aLower = a.toLowerCase();
        isUnknown = UNKNOWN_PHRASES.some(p => aLower.includes(p.toLowerCase()));
      }
    }
  } catch (e) {
    isUnknown = false;
  }

  return {
    json: {
      timestamp: new Date().toISOString(),
      inputType,
      question,
      answer,
      respondedWithAudio,
      matchType,
      answerHash: simpleHash(normalizedAnswer),
      sessionId,
      questionHash,
      normalizedQuestion,
      latencyMs,
      isUnknown,
      intent,
      language,
      rawQuestion,
      corrections
    }
  };
});

// Split the answer into up to MAX_CHUNKS balanced chunks for parallel TTS.
// Strategy: mask spans we must never split inside (URLs, emails, abbreviations,
// decimals), split on sentence-ending punctuation, then unmask and balance.
const MAX_CHUNKS = 4;
const MIN_CHUNK_CHARS = 40;
const MIN_SPLIT_CHARS = 100; // below this, splitting costs more overhead than it saves

const answer = String($json.answer || '').trim();

if (answer.length < MIN_SPLIT_CHARS) {
  return [{ json: { chunkIndex: 0, text: answer, totalChunks: 1 } }];
}

const PROTECT = [
  /\b(?:https?:\/\/|www\.)\S+/gi,
  /\b[\w.+-]+@[\w-]+\.[\w.]+/gi,
  /\b(?:Dr|Prof|Mr|Mrs|Ms|Jr|Sr|St|No|vs|etc|Inc|Ltd|approx|Fig|Vol)\./gi,
  /\b\d+\.\d+/g,
];

// Private-use sentinels so placeholders can never collide with real digits in
// the text (a plain " 12 " placeholder would match years like " 1996 ").
const stash = [];
let masked = answer;
for (const re of PROTECT) {
  masked = masked.replace(re, (m) => '' + (stash.push(m) - 1) + '');
}

// Sentence end = . ! ? or Arabic question mark (U+061F), followed by whitespace
// or end of string. Arabic comma (U+060C) is deliberately NOT a sentence end.
const rawParts = [];
let start = 0;
const sentenceEnd = /[.!?؟]/g;
let m;
while ((m = sentenceEnd.exec(masked)) !== null) {
  const next = masked[m.index + 1];
  if (next === undefined || /\s/.test(next)) {
    rawParts.push(masked.slice(start, m.index + 1));
    start = m.index + 1;
  }
}
if (start < masked.length) rawParts.push(masked.slice(start));

const unmask = (s) => s.replace(/(\d+)/g, (_, i) => stash[Number(i)]);
const sentences = rawParts.map(unmask).map((s) => s.trim()).filter(Boolean);

if (sentences.length <= 1) {
  return [{ json: { chunkIndex: 0, text: answer, totalChunks: 1 } }];
}

// Wall-clock for the parallel fan-out is the LONGEST chunk, not the total, so
// partition to minimise the maximum chunk size (classic linear-partition DP).
// Greedy packing overshoots and leaves lopsided chunks like 237/157.
const n = sentences.length;
const k = Math.min(MAX_CHUNKS, n);
const prefix = [0];
for (let i = 0; i < n; i++) prefix.push(prefix[i] + sentences[i].length);

const dp = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(Infinity));
const cut = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(0));
dp[0][0] = 0;
for (let i = 1; i <= n; i++) {
  for (let j = 1; j <= k; j++) {
    for (let p = j - 1; p < i; p++) {
      const worst = Math.max(dp[p][j - 1], prefix[i] - prefix[p]);
      if (worst < dp[i][j]) {
        dp[i][j] = worst;
        cut[i][j] = p;
      }
    }
  }
}

const bounds = [n];
let i = n;
for (let j = k; j > 0; j--) {
  bounds.unshift(cut[i][j]);
  i = cut[i][j];
}

const chunks = [];
for (let b = 0; b < bounds.length - 1; b++) {
  const piece = sentences.slice(bounds[b], bounds[b + 1]).join(' ').trim();
  if (piece) chunks.push(piece);
}

// Fold away chunks too small to be worth their own request.
for (let i = 0; i < chunks.length && chunks.length > 1; ) {
  if (chunks[i].length < MIN_CHUNK_CHARS) {
    if (i < chunks.length - 1) chunks[i + 1] = chunks[i] + ' ' + chunks[i + 1];
    else chunks[i - 1] = chunks[i - 1] + ' ' + chunks[i];
    chunks.splice(i, 1);
  } else i++;
}

return chunks.map((text, idx) => ({
  json: { chunkIndex: idx, text, totalChunks: chunks.length },
}));

const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const verdict = raw.trim().toUpperCase();
// A blank/failed judge reply must fall through to the agent, not serve a hit.
const isSame = verdict.includes('SAME') && !verdict.includes('DIFFERENT');
const lookup = $('Semantic Lookup').first().json;
return [{ json: {
  isSame,
  verdict: verdict || '(empty)',
  candidateHash: lookup.candidateHash || '',
  candidateScore: lookup.candidateScore,
} }];

// ============================================================================
