    { "canonical": "Abdul Amir Qablan", "aliases": ["abdul amir kablan","abdulamir qablan","abdel amir qablan","abdul amir cablan"], "fuzzy": true },
    { "canonical": "Hassan Al-Laqis", "aliases": ["hassan lakis","hassan al-laqees","hassan alaqis","hassan al akis","hassan el laqis"], "fuzzy": true },
    { "canonical": "Rodayna Hmede", "aliases": ["rudayna hmaidi","rodina hmede","rudaina hmede","rodaina hmadeh"], "fuzzy": true },
    { "canonical": "HCERES", "aliases": ["h series","aitch ceres","h ceres","aitch series","hseries"], "fuzzy": false },
    { "canonical": "ECTS", "aliases": ["e c t s","ects","eects","e cts"], "fuzzy": false },
    { "canonical": "Baccalaureate", "aliases": ["baccalaureat","bacalaureate","baccalaureah","the bac","bacc","baccalaureah degree"], "fuzzy": true },
    { "canonical": "Order of Engineers", "aliases": ["order of engineering","order engineers","order of the engineers"], "fuzzy": true }
  ]
};

function normalizeArabic(s) {
  return String(s)
    .replace(/[\u064B-\u065F\u0670\u06D6-\u06ED]/g, '') // diacritics (tashkeel), explicit non-overlapping ranges
    .replace(/ـ/g, '')                             // tatweel
    .replace(/[أإآ]/g, 'ا')         // hamza-alef forms -> bare alef
    .replace(/ة/g, 'ه')                       // ta-marbuta -> ha
    .replace(/ى/g, 'ي');                      // alef-maksura -> ya
}

function normToken(raw) {
  // lowercase (no-op for Arabic) + Arabic normalization. The tokenizer's
  // character class excludes Arabic punctuation, so tokens arrive clean.
  return normalizeArabic(String(raw).toLowerCase());
}

function levenshtein(a, b) {
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  let prev = new Array(n + 1);
  let curr = new Array(n + 1);
  for (let j = 0; j <= n; j++) prev[j] = j;
  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(
        prev[j] + 1,      // deletion
        curr[j - 1] + 1,  // insertion
        prev[j - 1] + cost // substitution
      );
    }
    const tmp = prev; prev = curr; curr = tmp;
  }
  return prev[n];
}

// Coarse phonetic skeleton: first char + remaining consonants (vowels
// dropped), used only as a small similarity booster - not a primary key.
function phoneticKey(s) {
  const str = String(s).toLowerCase();
  if (!str) return '';
  const first = str[0];
  const rest = str.slice(1).replace(/[aeiou]/g, '');
  return first + rest;
}

function similarity(a, b) {
  const na = normToken(a), nb = normToken(b);
  if (na === nb) return 1;
  const dist = levenshtein(na, nb);
  const maxLen = Math.max(na.length, nb.length) || 1;
  let sim = 1 - dist / maxLen;
  if (phoneticKey(na) === phoneticKey(nb) && phoneticKey(na) !== '') {
    sim = Math.min(1, sim + 0.05);
  }
  return sim;
}

// Extract word-like tokens (Latin + Arabic) with their [start,end) offsets
// into the ORIGINAL string, so corrections can be spliced back in without
// disturbing any surrounding punctuation/whitespace.
function tokenize(text) {
  // U+0600-U+06FF is the whole Arabic block, punctuation included: the question
  // mark U+061F, comma U+060C, semicolon U+061B and full stop U+06D4 all live in
  // it. Matching the block wholesale made "خلدة؟" a single token, which then failed to
  // match the alias "خلدة" exactly and scored into the clarify band — so a correctly
  // spoken Arabic question came back as "did you mean...?". English never showed
  // this because '?' is outside [A-Za-z]. Letters and combining marks only:
  const re = /[A-Za-z'ؐ-ؚؠ-٩ٮ-ۓە-ۿ]+/g;
  const tokens = [];
  let match;
  while ((match = re.exec(text)) !== null) {
    tokens.push({ raw: match[0], start: match.index, end: match.index + match[0].length, norm: normToken(match[0]) });
  }
  return tokens;
}

function isArabicText(text) {
  return /[؀-ۿ]/.test(text);
}

function buildClarifyPrompt(lang, heardRaw, candidateNames) {
  if (lang === 'ar') {
    const opts = candidateNames.length > 1 ? candidateNames.join(' أو ') : candidateNames[0];
    let p = `سمعت "${heardRaw}". هل تقصد ${opts}؟ يرجى السؤال مرة أخرى.`;
    if (p.length > 250) p = p.slice(0, 247) + '...';
    return p;
  }
  const opts = candidateNames.length > 1 ? candidateNames.join(' or ') : candidateNames[0];
  let p = `I heard "${heardRaw}". Did you mean ${opts}? Please ask again.`;
  if (p.length > 250) p = p.slice(0, 247) + '...';
  return p;
}

/**
 * Core entry point. Returns:
 * { userText, userTextRaw, corrections, needsClarification, clarifyCandidates, clarifyPrompt, lexiconSource }
 */
function correctText(inputText, lexicon, lexiconSource, inputType) {
  const text = String(inputText || '');
  // Typed input is treated more decisively than speech: a typed near-miss is
  // almost always a slip of the fingers, whereas a spoken near-miss can be a
  // genuinely different word (Whisper hears "IOM", a real organisation).
  // Unknown input type falls back to the conservative speech behaviour.
  const isTyped = inputType === 'text';
  const userTextRaw = text;
  const th = (lexicon && lexicon.thresholds) || DEFAULT_LEXICON.thresholds;
  const stoplist = new Set(((lexicon && lexicon.stoplist) || DEFAULT_LEXICON.stoplist).map(s => s.toLowerCase()));
  const terms = (lexicon && Array.isArray(lexicon.terms)) ? lexicon.terms : DEFAULT_LEXICON.terms;

  if (!text.trim()) {
    return { userText: text, userTextRaw, corrections: [], needsClarification: false, clarifyCandidates: [], clarifyPrompt: '', lexiconSource };
  }

  const tokens = tokenize(text);
  if (tokens.length === 0) {
    return { userText: text, userTextRaw, corrections: [], needsClarification: false, clarifyCandidates: [], clarifyPrompt: '', lexiconSource };
  }

  // Build a flat alias index: normalized alias string (space-joined tokens) -> {canonical, fuzzy}
  const aliasIndex = new Map();
  const fuzzyAliasList = []; // { alias, canonical }
  for (const term of terms) {
    for (const alias of (term.aliases || [])) {
      const normAlias = normToken(alias).trim();
      aliasIndex.set(normAlias, { canonical: term.canonical, fuzzy: !!term.fuzzy });
      if (term.fuzzy) fuzzyAliasList.push({ alias: normAlias, canonical: term.canonical });
    }
  }

  const consumed = new Array(tokens.length).fill(false);
  const corrections = [];
  const replacements = []; // {start, end, text}

  // --- Tier A: exact alias n-grams, longest (4) first ---
  for (let n = 4; n >= 1; n--) {
    for (let i = 0; i + n <= tokens.length; i++) {
      if (consumed.slice(i, i + n).some(Boolean)) continue;
      const span = tokens.slice(i, i + n);
      const normPhrase = span.map(t => t.norm).join(' ');
      const hit = aliasIndex.get(normPhrase);
      if (hit) {
        for (let k = i; k < i + n; k++) consumed[k] = true;
        const start = span[0].start, end = span[span.length - 1].end;
        const originalSpan = text.slice(start, end);
        if (originalSpan.toLowerCase() !== hit.canonical.toLowerCase()) {
          replacements.push({ start, end, text: hit.canonical });
          corrections.push({ from: originalSpan, to: hit.canonical, score: 1.0, tier: 'A' });
        }
      }
    }
  }

  // --- Tier B / Tier C: fuzzy single-token matching on remaining tokens ---
  const clarifyCandidatesAll = [];
  for (let i = 0; i < tokens.length; i++) {
    if (consumed[i]) continue;
    const tok = tokens[i];
    if (tok.norm.length < th.minFuzzyLen) continue;
    if (stoplist.has(tok.norm)) continue;

    // Score each CANONICAL term by its best-matching alias, then rank across
    // distinct terms. Ranking raw aliases instead lets two spellings of the
    // same term ("wardania" / "wardaniyeh") look like an ambiguous tie, which
    // blocked every fuzzy correction for terms carrying several aliases.
    const bestPerTerm = new Map();
    for (const fa of fuzzyAliasList) {
      const sim = similarity(tok.norm, fa.alias);
      const prev = bestPerTerm.get(fa.canonical);
      if (prev === undefined || sim > prev) bestPerTerm.set(fa.canonical, sim);
    }
    let best = null, second = null;
    for (const entry of bestPerTerm) {
      const canonical = entry[0], sim = entry[1];
      if (!best || sim > best.sim) { second = best; best = { sim, canonical }; }
      else if (!second || sim > second.sim) { second = { sim, canonical }; }
    }
    if (!best) continue;

    const gapOk = !second || (best.sim - second.sim) >= th.gap;

    const autoBand = best.sim >= th.autoApply && gapOk;
    const uncertainBand = best.sim >= th.clarify && (best.sim < th.autoApply || !gapOk);

    // For typed turns the uncertain band auto-applies instead of asking; a true
    // tie (two candidates within `gap`) still asks, on either input type.
    if (autoBand || (uncertainBand && isTyped && gapOk)) {
      consumed[i] = true;
      if (tok.raw.toLowerCase() !== best.canonical.toLowerCase()) {
        replacements.push({ start: tok.start, end: tok.end, text: best.canonical });
        corrections.push({ from: tok.raw, to: best.canonical, score: Number(best.sim.toFixed(3)), tier: autoBand ? 'B' : 'B-typed' });
      }
    } else if (uncertainBand) {
      const cands = [best.canonical];
      if (second && second.canonical !== best.canonical) cands.push(second.canonical);
      clarifyCandidatesAll.push({ token: tok.raw, candidates: cands.slice(0, 2), score: Number(best.sim.toFixed(3)) });
    }
  }

  // Apply replacements (splice from the end so earlier offsets stay valid)
  replacements.sort((a, b) => b.start - a.start);
  let corrected = text;
  for (const r of replacements) {
    corrected = corrected.slice(0, r.start) + r.text + corrected.slice(r.end);
  }

  const lang = isArabicText(text) ? 'ar' : 'en';
  let needsClarification = false;
  let clarifyPrompt = '';
  let clarifyCandidates = [];
  if (clarifyCandidatesAll.length > 0) {
    needsClarification = true;
    const top = clarifyCandidatesAll[0];
    clarifyCandidates = top.candidates;
    clarifyPrompt = buildClarifyPrompt(lang, top.token, top.candidates);
  }

  return {
    userText: needsClarification ? text : corrected, // never rewrite on a clarification turn
    userTextRaw,
    corrections,
    needsClarification,
    clarifyCandidates,
    clarifyPrompt,
    lexiconSource
  };
}

// ============================================================================
// n8n glue (this is the part that actually runs inside the Code node).
// Guarded so requiring this file under bun for unit tests does not execute it.
// ============================================================================
if (typeof $input === 'undefined') {
  if (typeof module !== 'undefined') {
    module.exports = { correctText, DEFAULT_LEXICON, levenshtein, similarity, normalizeArabic, tokenize };
  }
} else {
  const items = $input.all();

  let rawUserText = '';
  try {
    rawUserText = $('Set userText (Text)').first().json.userText;
  } catch (e) {
    rawUserText = '';
  }
  rawUserText = rawUserText || '';

  let lexicon = null;
  let lexiconSource = 'fallback';
  try {
    const raw = items[0] && items[0].json ? items[0].json.value : null;
    if (raw) {
      lexicon = typeof raw === 'string' ? JSON.parse(raw) : raw;
      lexiconSource = 'db';
    }
  } catch (e) {
    lexicon = null;
    lexiconSource = 'fallback';
  }
  if (!lexicon || !Array.isArray(lexicon.terms)) {
    lexicon = DEFAULT_LEXICON;
    lexiconSource = 'fallback';
  }

  // The client tags each turn's origin (sendChat in web/src/lib/api.ts), because
  // speech arrives here already transcribed and is otherwise indistinguishable
  // from typing. Anything absent or unrecognised reads as 'text'.
  let inputType = 'text';
  try {
    inputType = $('Set userText (Text)').first().json.inputType === 'audio'
      ? 'audio'
      : 'text';
  } catch (e) {
    inputType = 'text';
  }

  let result;
  try {
    result = correctText(rawUserText, lexicon, lexiconSource, inputType);
  } catch (e) {
    result = {
      userText: rawUserText,
      userTextRaw: rawUserText,
      corrections: [],
      needsClarification: false,
      clarifyCandidates: [],
      clarifyPrompt: '',
      lexiconSource: 'fallback-error'
    };
  }

  // --- correctedHash: same djb2 + normalization as Normalize & Hash Question,
  // copied verbatim so the two hashes can never drift apart. Used for the
  // cache dual-write (raw hash + corrected-text hash). ---
  function simpleHash(str) {
    let hash = 5381;
    for (let i = 0; i < str.length; i++) {
      hash = ((hash << 5) + hash) + str.charCodeAt(i);
      hash = hash & hash;
    }
    return (hash >>> 0).toString(16);
  }
  result.inputType = inputType;
  const correctedNormalized = String(result.userText || '').toLowerCase().trim().replace(/[^\w\s\u0600-\u06FF]/g, '').replace(/\s+/g, ' ');
  result.correctedHash = simpleHash(correctedNormalized);

  return [{ json: result }];
}

// Deterministic point id from the question hash, so re-asking the same
// question overwrites its vector instead of duplicating it.
const items = $input.all();
try {
  if (!$('Embed Question').isExecuted) return items;
  const vec = $('Embed Question').first().json.embedding?.values;
  if (!vec || !vec.length) return items;
  const nh = $('Normalize & Hash Question').first().json;
  const id = parseInt(nh.questionHash, 16);
  if (!Number.isFinite(id)) return items;
  let correctedQuestion = nh.userText;
  try {
    if ($('Correct Domain Terms').isExecuted) {
      correctedQuestion = $('Correct Domain Terms').first().json.userText;
    }
  } catch (eCdt) {
    // keep raw fallback
  }
  await this.helpers.httpRequest({
    method: 'PUT',
    url: 'http://qdrant:6333/collections/faq_cache/points',
    body: { points: [{ id, vector: vec, payload: {
      questionHash: nh.questionHash, question: correctedQuestion } }] },
    json: true,
  });
} catch (e) {
  // Indexing is best-effort; never break the response over it.
}
return items;

