// Qdrant needs no auth, so call it straight from the Code node.
// Any failure here must degrade to a normal cache miss, never break the turn.
const vec = $json.embedding && $json.embedding.values;
if (!vec || !vec.length) return [{ json: { candidateFound: false } }];
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://qdrant:6333/collections/faq_cache/points/search',
    body: { vector: vec, limit: 3, with_payload: true, score_threshold: 0.8 },
    json: true,
  });
  const top = res && res.result && res.result[0];
  if (!top || !top.payload || !top.payload.questionHash) {
    return [{ json: { candidateFound: false } }];
  }
  return [{ json: {
    candidateFound: true,
    candidateHash: top.payload.questionHash,
    candidateQuestion: top.payload.question,
    candidateScore: top.score,
  } }];
} catch (e) {
  return [{ json: { candidateFound: false, lookupError: String(e).slice(0, 200) } }];
}
